    .reset_pixel_n        (reset_pixel_n),
    .clk_esc              (clk),
    .reset_esc_n          (reset_n),
    .phy_clk_byte_HS      (clk_byte_HS),
    
    .axi_clk              (axi_clk),
    .axi_reset_n          (axi_reset_n),
    .axi_awaddr           (axi_awaddr),
